import{_ as r,o as t,c as e,ab as n}from"./chunks/framework.DCf1Sbhf.js";const m=JSON.parse('{"title":"微前端","description":"","frontmatter":{},"headers":[],"relativePath":"front/micro/index.md","filePath":"front/micro/index.md","lastUpdated":1774836195000}'),i={name:"front/micro/index.md"};function p(l,o,a,s,d,c){return t(),e("div",null,[...o[0]||(o[0]=[n('<h1 id="微前端" tabindex="-1">微前端 <a class="header-anchor" href="#微前端" aria-label="Permalink to &quot;微前端&quot;">​</a></h1><p>微前端是一种多个团队通过独立发布功能的方式来共同构建现代化 web 应用的技术手段及方法策略。</p><p>微前端架构旨在解决单体应用在一个相对长的时间跨度下，由于参与的人员、团队的增多、变迁，从一个普通应用演变成一个<strong>巨石应用</strong>(Frontend Monolith)后，随之而来的应用不可维护的问题。</p><p><strong>微前端架构的核心价值：</strong></p><ol><li><p>技术栈无关</p><p>主框架不限制接入应用的技术栈，微应用具备完全自主权</p></li><li><p>独立开发、独立部署</p><p>微应用仓库独立，前后端可独立开发，部署完成后主框架自动完成同步更新</p></li><li><p>增量升级</p><p>在面对各种复杂场景时，我们通常很难对一个已经存在的系统做全量的技术栈升级或重构，而微前端是一种非常好的实施渐进式重构的手段和策略</p></li><li><p>独立运行时</p><p>每个微应用之间状态隔离，运行时状态不共享</p></li></ol><h1 id="微前端-micro-frontend-和-monorepo" tabindex="-1">微前端（Micro Frontend） 和 Monorepo <a class="header-anchor" href="#微前端-micro-frontend-和-monorepo" aria-label="Permalink to &quot;微前端（Micro Frontend） 和 Monorepo&quot;">​</a></h1><ol><li><p>Monorepo：代码组织方式</p><p>把多个项目 / 包放在同一个 Git 仓库里管理，解决<strong>代码复用、版本统一、构建效率</strong>问题。</p></li><li><p>微前端：运行时架构</p><p>多个独立应用在浏览器运行时组合成一个系统，解决<strong>独立部署、技术栈无关、团队自治问题</strong>。</p></li></ol><p><strong>区别：</strong></p><ul><li>Monorepo 是工程化方案，解决代码复用与版本一致性问题。</li><li>微前端是运行时架构，解决应用解耦与独立部署问题。</li><li>两者不冲突，大型项目通常一起用。 <ul><li>Monorepo 管理：公共组件、工具、类型、工具链</li><li>微前端管理：业务微应用（独立部署）</li></ul></li></ul>',9)])])}const f=r(i,[["render",p]]);export{m as __pageData,f as default};
